# A small functional toolkit
def pluck_deep(key):
    return lambda obj: reduce(lambda acc, k: acc[k], key.split('.'), obj)

def compose(*fns):
    return lambda res: reduce(lambda acc, fn: fn(acc), fns, res)

def unfold(f, seed):
    """Build a list by repeatedly applying f to a seed."""
    acc = []
    while True:
        result = f(seed)
        if result is None:
            return acc
        acc.append(result[0])
        seed = result[1]
